import assert from 'node:assert/strict';
import { Telemetry, observedJob, evaluateAlerts } from '../../dist/packages/observability/src/index.js';
import { createGatewayServer } from '../../dist/apps/gateway/src/index.js';
import { createAuthzFixture } from '../../dist/apps/gateway/test/helpers/authz.js';

// Fresh test keys only, generated by the existing authz fixture. No environment credentials.
const telemetry = new Telemetry('local');
const audit = [];
const fixture = await createAuthzFixture({ auditSink: { record: event => audit.push(event) } });
let failing = true;
const sentinel = 'SYNTHETIC_ONLY_PRIVATE_FAILURE_903';
const adapter = { callTool: async () => observedJob(async () => {
  if (failing) throw new Error(sentinel);
  return { ok: true, content: [] };
}, telemetry) };
const server = createGatewayServer(adapter, undefined, fixture.middleware, undefined, null, telemetry);
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
try {
  const origin = `http://127.0.0.1:${server.address().port}`;
  const requests = [];
  for (let i = 0; i < 6; i++) {
    if (i === 5) failing = false;
    const response = await fetch(`${origin}/mcp/tools/call`, {
      method: 'POST', headers: { 'x-actor-assertion': await fixture.mint(), 'x-request-id': sentinel },
      body: JSON.stringify({ name: 'synthetic', arguments: { private: sentinel } }),
    });
    await response.text(); assert.equal(response.status, i < 5 ? 502 : 200);
    requests.push({ status: response.status, traceId: response.headers.get('x-request-id') });
  }
  const snapshot = await telemetry.snapshot();
  assert.equal(snapshot.events.length, 12);
  for (const [i, request] of requests.entries()) {
    assert.equal(audit[i].requestId, request.traceId);
    const linked = snapshot.events.filter(e => e.contexts.trace.trace_id === request.traceId);
    assert.equal(linked.length, 2);
    const worker = linked.find(e => e.tags.component === 'worker');
    const gateway = linked.find(e => e.tags.component === 'gateway');
    assert.equal(worker.contexts.trace.parent_span_id, gateway.contexts.trace.span_id);
  }
  const alerts = evaluateAlerts(snapshot);
  assert.ok(alerts.some(a => a.code === 'journey_failures'));
  const evidence = { mode: 'local-only', externalIngestion: false, failures: 5, recoveryStatus: 200,
    auditCorrelation: '6/6', gatewayWorkerCorrelation: '6/6', privateSentinelAbsent: true, alerts, ...snapshot };
  assert.ok(!JSON.stringify(evidence).includes(sentinel));
  process.stdout.write(`${JSON.stringify(evidence, null, 2)}\n`);
} finally {
  server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); await telemetry.close();
}
